BEGIN; DO $$ DECLARE uid uuid; failed boolean; cid uuid; co uuid; beforedate date; BEGIN SELECT user_id INTO uid FROM public.clients WHERE user_id IS NOT NULL AND status='active' AND NOT churned LIMIT 1; PERFORM set_config('request.jwt.claim.sub',uid::text,true);SET LOCAL ROLE authenticated;failed:=false;BEGIN PERFORM public.run_finance_automation();EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Client ran finance';END IF;RESET ROLE;SET LOCAL ROLE anon;failed:=false;BEGIN PERFORM public.run_finance_automation();EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Anon ran finance';END IF;RESET ROLE;PERFORM set_config('request.jwt.claim.sub','957e2e55-69ed-4e12-bcc0-529ea83380a5',true);INSERT INTO public.clients(name,status,churned,churn_date,churn_reason)VALUES('QA closed renewal','inactive',true,current_date,'QA rollback')RETURNING id INTO cid;INSERT INTO public.finance_contracts(client_id,amount,start_date,end_date,status,auto_renew,periodicity,auto_billing)VALUES(cid,100,current_date-60,current_date-1,'active',true,'monthly',true)RETURNING id,end_date INTO co,beforedate;SET LOCAL ROLE authenticated;PERFORM public.run_finance_automation();IF EXISTS(SELECT 1 FROM public.finance_contracts WHERE id=co AND end_date<>beforedate) THEN RAISE EXCEPTION 'Closed client renewed';END IF;IF EXISTS(SELECT 1 FROM public.finance_charges WHERE client_id=cid) THEN RAISE EXCEPTION 'Closed client billed';END IF;RESET ROLE;END $$;ROLLBACK;SELECT 'PASS: anonymous and client automation denied; finance editor allowed; closed account not renewed or billed' result;
